<script setup lang="ts">import { ref } from 'vue'; import { copy } from '../lib/format'; import { errorText } from '../lib/api'; import Icon from './Icon.vue'; import Notice from './Notice.vue'; const props = defineProps<{ code: string; language?: string }>(); const message = ref(''); const failed = ref(false); async function doCopy() { try { await copy(props.code); message.value = '已复制'; failed.value = false } catch(e) { message.value = errorText(e); failed.value = true } }</script><template><div class="code-block"><header><span>{{ language || 'CODE' }}</span><button class="code-copy" type="button" @click="doCopy"><Icon name="copy" :size="15" />复制</button></header><pre tabindex="0"><code>{{ code }}</code></pre></div><Notice :message="message" :kind="failed ? 'error' : 'success'" /></template>